//! Parity and regression tests for the Irodori TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_irodori_tts/`, generated by
//! `tools/gen_irodori_tts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (the llm-jp tokenizer
//! replaced by a deterministic offline mock, the DACVAE codec bundled
//! as the `dacvae/` checkpoint), records every `mx.random.normal`
//! draw, and verifies each sampler replay against the reference
//! sampler entry point on the Python side (the batched-CFG kernel
//! fusion drift stays under 1e-4 over the Euler steps; the sequential
//! replay is the pinned path the Rust tests compare against).

use std::collections::VecDeque;
use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{build_duration_features, FlowNoise, GenerateParams, Model, SeededFlowNoise};
use crate::SpeechError;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_irodori_tts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn bool_vec(value: &Value) -> Vec<bool> {
    value
        .as_array()
        .expect("mask")
        .iter()
        .map(|v| v.as_bool().expect("flag"))
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

// Measured maxima when the gates were frozen; assertions use these
// values, not re-measured ones. The per-step sampler traces grow
// through the Euler feedback (each x_t feeds the next velocity), so
// the latent gate covers three accumulations while the duration,
// codec, and MeanFlow stages stay tight.
const STAGE_TOLERANCE: f32 = 2e-5;
const STEP_TOLERANCE: f32 = 2e-4;
const WAVEFORM_TOLERANCE: f32 = 1e-3;

/// The recorded `mx.random.normal` draws replayed in reference order.
pub(crate) struct ReplayNoise {
    draws: VecDeque<(usize, Vec<f32>)>,
}

impl ReplayNoise {
    pub(crate) fn from_trace(traces: &Value) -> Self {
        let draws: Vec<(usize, Vec<f32>)> = traces["noise_draws"]
            .as_array()
            .expect("draws")
            .iter()
            .map(|draw| {
                (
                    draw["shape"]
                        .as_array()
                        .expect("shape")
                        .iter()
                        .map(|v| v.as_u64().expect("dim") as usize)
                        .product::<usize>(),
                    f32_vec(&draw["values"]),
                )
            })
            .collect();
        Self {
            draws: VecDeque::from(draws),
        }
    }
}

impl FlowNoise for ReplayNoise {
    fn normal(&mut self, n: usize) -> Vec<f32> {
        let (recorded, values) = self
            .draws
            .pop_front()
            .expect("the fixture ran out of recorded draws");
        assert_eq!(
            recorded, n,
            "recorded draw shape does not match the request"
        );
        values
    }
}

struct CasePrompt {
    ids: Vec<i32>,
    mask: Vec<bool>,
    caption_ids: Option<Vec<i32>>,
    caption_mask: Option<Vec<bool>>,
    ref_latent: Vec<f32>,
    ref_rows: usize,
    ref_mask: Vec<bool>,
}

fn case_prompt(traces: &Value) -> CasePrompt {
    let prompt = &traces["prompt"];
    CasePrompt {
        ids: i32_vec(&prompt["ids"]),
        mask: bool_vec(&prompt["mask"]),
        caption_ids: prompt
            .get("caption_ids")
            .filter(|v| !v.is_null())
            .map(i32_vec),
        caption_mask: prompt
            .get("caption_mask")
            .filter(|v| !v.is_null())
            .map(bool_vec),
        ref_latent: f32_vec(&prompt["ref_latent"]),
        ref_rows: prompt["ref_rows"].as_u64().unwrap() as usize,
        ref_mask: bool_vec(&prompt["ref_mask"]),
    }
}

/// The fixture feature builder: the reference runs
/// `build_duration_features` over the normalized text with the token
/// count from the mask.
fn duration_features(traces: &Value) -> Vec<f32> {
    let token_count = traces["prompt"]["mask"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|v| v.as_bool().unwrap())
        .count();
    build_duration_features(
        traces["normalized_text"].as_str().unwrap(),
        token_count,
        24,
        true,
    )
}

#[test]
fn duration_case_predicts_the_reference_frames() {
    let traces = read_json(&testdata("duration/traces.json"));
    let model = Model::open(&testdata("duration")).expect("family model loads");

    // The 14-dim features over the caller-normalized text.
    let features = duration_features(&traces);
    let diff = max_abs_diff(&features, &f32_vec(&traces["features"]));
    assert!(diff <= STAGE_TOLERANCE, "features diff {diff}");

    // The predictor's log-frames ride the latent length: the clamped
    // step count pins the whole duration chain exactly.
    let prompt = case_prompt(&traces);
    // The duration case runs no sampler and records no draws.
    let mut noise = SeededFlowNoise::new(0);
    let generated = model
        .generate_latents(
            &prompt.ids,
            &prompt.mask,
            None,
            None,
            Some((&prompt.ref_latent, prompt.ref_rows, Some(&prompt.ref_mask))),
            &GenerateParams {
                duration_scale: traces["duration_scale"].as_f64().unwrap() as f32,
                min_seconds: 0.1,
                max_seconds: 0.2,
                ..GenerateParams::default()
            },
            Some(&features),
            &mut noise,
        )
        .expect("latents");
    let frames = generated.latent.len() / 8;
    assert_eq!(frames, traces["latent_steps"].as_u64().unwrap() as usize);
}

#[test]
fn generate_rf_case_replays_the_reference_run() {
    let traces = read_json(&testdata("generate_rf/traces.json"));
    let model = Model::open(&testdata("generate_rf")).expect("family model loads");
    let prompt = case_prompt(&traces);
    let features = duration_features(&traces);
    let diff = max_abs_diff(&features, &f32_vec(&traces["features"]));
    assert!(diff <= STAGE_TOLERANCE, "features diff {diff}");

    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(
            &prompt.ids,
            &prompt.mask,
            prompt.caption_ids.as_deref(),
            prompt.caption_mask.as_deref(),
            Some((&prompt.ref_latent, prompt.ref_rows, Some(&prompt.ref_mask))),
            &GenerateParams {
                rng_seed: traces["rng_seed"].as_u64().unwrap(),
                min_seconds: 0.1,
                max_seconds: 0.2,
                ..GenerateParams::default()
            },
            Some(&features),
            &mut noise,
        )
        .expect("generate");
    assert!(noise.draws.is_empty(), "draws left unconsumed");

    let steps = traces["steps"].as_array().expect("steps");
    assert_eq!(steps.len(), 3);
    assert_eq!(generated.latent_steps, 300);
    let diff = max_abs_diff(&generated.latent, &f32_vec(&traces["latent"]));
    assert!(diff <= STEP_TOLERANCE, "latent diff {diff}");
    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
    assert_eq!(
        generated.samples.len(),
        traces["trim"].as_u64().unwrap() as usize
    );
    assert_eq!(generated.sample_rate, 24000);
}

#[test]
fn generate_joint_case_replays_the_reference_run() {
    let traces = read_json(&testdata("generate_joint/traces.json"));
    let model = Model::open(&testdata("generate_joint")).expect("family model loads");
    let prompt = case_prompt(&traces);
    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(
            &prompt.ids,
            &prompt.mask,
            None,
            None,
            Some((&prompt.ref_latent, prompt.ref_rows, Some(&prompt.ref_mask))),
            &GenerateParams {
                rng_seed: traces["rng_seed"].as_u64().unwrap(),
                seconds: Some(traces["seconds"].as_f64().unwrap() as f32),
                min_seconds: 0.1,
                max_seconds: 0.2,
                cfg_scale_text: Some(2.0),
                cfg_scale_speaker: Some(2.0),
                cfg_min_t: Some(0.3),
                speaker_kv_scale: Some(0.9),
                speaker_kv_min_t: Some(0.7),
                ..GenerateParams::default()
            },
            None,
            &mut noise,
        )
        .expect("generate");
    assert!(noise.draws.is_empty(), "draws left unconsumed");
    let diff = max_abs_diff(&generated.latent, &f32_vec(&traces["latent"]));
    assert!(diff <= STEP_TOLERANCE, "latent diff {diff}");
    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
    // The speaker-KV rollback fired in the reference run.
    assert!(
        traces["steps"].as_array().unwrap().iter().any(|step| {
            let t = step["t"].as_f64().unwrap() as f32;
            let t_next = step["t_next"].as_f64().unwrap() as f32;
            t_next < 0.7 && 0.7 <= t
        }),
        "expected the rollback step"
    );
}

#[test]
fn meanflow_case_replays_the_reference_run() {
    let traces = read_json(&testdata("meanflow/traces.json"));
    let model = Model::open(&testdata("meanflow")).expect("family model loads");
    let prompt = case_prompt(&traces);
    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(
            &prompt.ids,
            &prompt.mask,
            None,
            None,
            Some((&prompt.ref_latent, prompt.ref_rows, Some(&prompt.ref_mask))),
            &GenerateParams {
                rng_seed: traces["rng_seed"].as_u64().unwrap(),
                seconds: Some(0.1),
                min_seconds: 0.1,
                max_seconds: 0.2,
                ..GenerateParams::default()
            },
            None,
            &mut noise,
        )
        .expect("generate");
    assert!(noise.draws.is_empty(), "draws left unconsumed");
    // MeanFlow is single-branch per step; the cond_module drift
    // (about 3e-6 from SiLU/matmul ordering) accumulates over the three
    // Euler feedbacks, so the latent gate matches the RF step gate.
    let diff = max_abs_diff(&generated.latent, &f32_vec(&traces["latent"]));
    assert!(diff <= STEP_TOLERANCE, "latent diff {diff}");
    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
}

#[test]
fn codec_case_encodes_and_decodes_the_reference_audio() {
    let traces = read_json(&testdata("codec/traces.json"));
    let model = Model::open(&testdata("codec")).expect("family model loads");
    let audio = f32_vec(&traces["audio"]);
    let (latent, rows) = model
        .encode_ref_audio(&audio, None)
        .expect("encode ref audio");
    let diff = max_abs_diff(&latent, &f32_vec(&traces["ref_latent"]));
    assert!(diff <= STAGE_TOLERANCE, "ref latent diff {diff}");
    assert_eq!(rows, traces["ref_rows"].as_u64().unwrap() as usize);

    // Decode through the family tail (channel-last to channel-first
    // around the codec).
    let dim = traces["latent_dim"].as_u64().unwrap() as usize;
    let frames = rows;
    let mut channel_first = vec![0.0f32; frames * dim];
    for t in 0..frames {
        for d in 0..dim {
            channel_first[d * frames + t] = latent[t * dim + d];
        }
    }
    let decoded = model.decode_latents(&channel_first).expect("decode");
    let diff = max_abs_diff(&decoded, &f32_vec(&traces["decoded"]));
    assert!(diff <= STAGE_TOLERANCE, "decoded diff {diff}");
}

#[test]
fn seeded_threefry_reproduces_the_recorded_normal_draws() {
    for name in ["generate_rf", "generate_joint", "meanflow"] {
        let traces = read_json(&testdata(format!("{name}/traces.json").as_str()));
        let mut noise = SeededFlowNoise::new(traces["rng_seed"].as_u64().unwrap());
        for draw in traces["noise_draws"].as_array().expect("draws") {
            let values = f32_vec(&draw["values"]);
            let produced = noise.normal(values.len());
            let diff = max_abs_diff(&produced, &values);
            assert!(diff < 1e-6, "{name}: seeded draw diff {diff:e}");
        }
    }
}

#[test]
fn config_parses_and_resolves() {
    let fixture = read_json(&testdata("generate_rf/config.json"));
    let config = super::ModelConfig::from_json(&fixture).expect("config parses");
    assert_eq!(config.model_type, "irodori_tts");
    assert_eq!(config.sample_rate, 24000);
    assert_eq!(config.audio_downsample_factor, 8);
    assert!(config.dit.use_pretrained_text_encoder());
    assert!(!config.dit.use_meanflow());
    assert!(config.dit.use_caption_condition);
    assert!(config.dit.use_speaker_condition_resolved());
    assert_eq!(config.dit.caption_dim_resolved(), 32);
    assert_eq!(config.dit.patched_latent_dim(), 8);
    assert_eq!(config.dit.speaker_patched_latent_dim(), 16);
    assert_eq!(
        config.dit.duration_architecture,
        "token_sum_dual_adarn_zero_no_aux"
    );

    // Defaults fill every absent field (the reference dataclass).
    let resolved = super::ModelConfig::from_json(&serde_json::json!({})).unwrap();
    assert_eq!(resolved.sample_rate, 48000);
    assert_eq!(resolved.audio_downsample_factor, 1920);
    assert_eq!(resolved.dit.model_dim, 1280);
    assert_eq!(resolved.dit.num_layers, 12);
    assert_eq!(resolved.sampler.num_steps, 40);
    assert_eq!(resolved.sampler.cfg_guidance_mode, "independent");
    assert!(!resolved.dit.use_caption_condition);
    assert!(resolved.dit.use_speaker_condition_resolved());
    assert!((resolved.dit.caption_mlp_ratio_resolved() - 2.6).abs() < 1e-6);
}

#[test]
fn unsupported_paths_are_refused() {
    let dir = testdata("generate_rf");
    let model = Model::open(&dir).expect("model loads");
    let prompt = case_prompt(&read_json(&dir.join("traces.json")));

    // The duration path refuses missing features.
    let error = model
        .generate_latents(
            &prompt.ids,
            &prompt.mask,
            prompt.caption_ids.as_deref(),
            prompt.caption_mask.as_deref(),
            Some((&prompt.ref_latent, prompt.ref_rows, Some(&prompt.ref_mask))),
            &GenerateParams {
                rng_seed: 1,
                ..GenerateParams::default()
            },
            None,
            &mut SeededFlowNoise::new(1),
        )
        .expect_err("duration features required");
    assert!(matches!(error, SpeechError::Input { .. }));

    // Pooled duration architectures are refused at load.
    let mut config = read_json(&dir.join("config.json"));
    config["dit"]["duration_architecture"] = serde_json::json!("token_sum_pooled");
    config["dit"]["use_duration_predictor"] = serde_json::json!(true);
    let parsed = super::ModelConfig::from_json(&config).unwrap();
    let result = super::IrodoriDiT::load(&crate::lm::Weights::open(&dir).unwrap(), &parsed.dit);
    assert!(result.is_err(), "pooled duration architecture refused");
}
